        this.markHurt();
        Entity entity = p_70097_1_.getEntity();
        if (entity != null) {
            Vec3 vector3d = entity.getLookAngle();
            this.setDeltaMovement(vector3d);
            this.xPower = vector3d.x * 0.1D;
            this.yPower = vector3d.y * 0.1D;
